(()=>{'use strict';
const modes={
 timed:{title:'90 秒挑战',goal:'在 90 秒内收集星光，带着尽可能高的分数返航。',control:'拖动驾驶，或使用方向键 / WASD。空格加速，Q 切换月相。',hazard:'陨石从边缘进入；警戒线与落点预告危险。护盾耗尽就结束航程。',tip:'先看预警，再横向让开。加速带有短暂护盾，留给包围时突围。'},
 endless:{title:'无尽巡航',goal:'完成一段又一段 90 秒航程，在月港整备后继续远航。',control:'拖动或方向键驾驶；加速脱险。段间选择模块，准备好后再启航。',hazard:'越往深空，威胁越密集。多向陨石、交叉光束和雷暴会同时逼近。',tip:'不要追逐每一枚星光。预留退路，利用段间修复与补给。此说明只在新一局开始前出现。'},
 relax:{title:'星海漫游',goal:'收集星种，回到月港种下星座。没有倒计时，也没有碰撞失败。',control:'拖动或方向键自由驾驶。随时返航，按自己的节奏探索。',hazard:'这里无需与时间和护盾较量；航路上的发现都可以慢慢靠近。',tip:'循着星光探索，再带着星种返回月港。可以随时暂停。'},
 adventure:{title:'遗迹远征',goal:'穿过三个章节，在 180 秒内撤离。救援、档案与能源决定远征的收获。',control:'拖动或方向键驾驶，靠近航门选择路线。空格加速，Q 切换月相。',hazard:'任务路线与危险相交，追逐全部支线可能错过撤离时机。',tip:'先选一个明确目标，再观察剩余时间。遇到危险先保证撤离。'},
 center:{title:'中心对称',goal:'让本体与月影各自抵达对应的终点。',control:'每按一个方向，本体向该方向走一步，月影向相反方向走一步。',hazard:'墙会挡住角色；双方不能占据同一格。机关可能需要另一位角色保持供能。',tip:'让墙挡住其中一位，调整两人的相对位置。先观察两条路线再行动。'},
 relay:{title:'一人两角',goal:'轮流指挥本体与月影，让两位角色合作完成机关。',control:'方向键只移动当前角色；点击“换角色”或按 Tab 交棒。',hazard:'离开压板可能让门重新关闭。两位角色也会彼此挡路。',tip:'先安排一位守住机关，再换另一位穿门。需要时可以撤销一步。'},
 parallel:{title:'同向同行',goal:'用同一组方向指令，让两位角色抵达各自终点。',control:'每次输入，双方都向同一方向尝试走一步。',hazard:'不同的墙和岔路会让两人的位置逐渐错开。',tip:'利用墙壁停住一位，让另一位继续走，重新对齐位置。'},
 replay:{title:'双月回响',goal:'录下过去的自己，让月影与现在的本体合作开启通路。',control:'先录制路线，再开始回响。人走一步，影子推进一步；停下思考时，双方都不会前进。',hazard:'门与压板会互相依赖。影子抵达终点后会留在原地；回响路线不合适可能困住本体。',tip:'需要影子先走时，使用“等待一步”。先安排守门位置，再规划本体的路线；必要时重新录制。'},
 trails:{title:'月纹织路',goal:'完成月纹要求，再让两位角色抵达终点。',control:'按当前关卡的控制方式移动。已经走过的月纹会留下足迹。',hazard:'消耗过的月纹不能反复通过，另一位角色也不能再走。',tip:'先分好两人的路线，优先处理死路；撤销可以重新规划。'}
};
const worlds={classic:['拾光星海','留意分岔航门与各区域的预警；支线可以略过，安全返航也有价值。'],aurora:['极光航道','寻找光幕的安全间隙，精准穿幕积累共鸣；不要迎着危险光幕硬闯。'],warp:['折跃回廊','观察稳路与险径，再加速进入航门；折跃后先确认新的位置和退路。'],ion:['磁暴熔炉','按顺序接触节点，并切换到节点要求的明 / 暗月相。光束交叉处要提前绕开。'],station:['受损空间站','运送能源修复空间站，护送运输船；加速拦截来袭陨石，兼顾自己与空间站的护盾。']};
let sheet=null,pending=null,last=null,previousFocus=null,background=[];
function press(el,fn){let down=null;el.addEventListener('pointerdown',e=>{if(e.button!==0)return;down={x:e.clientX,y:e.clientY,id:e.pointerId};el.setPointerCapture?.(e.pointerId)});el.addEventListener('pointerup',e=>{const d=down;down=null;if(d&&d.id===e.pointerId&&Math.hypot(e.clientX-d.x,e.clientY-d.y)<14){e.preventDefault();fn()}});el.addEventListener('pointercancel',()=>down=null);el.addEventListener('lostpointercapture',()=>down=null);el.addEventListener('click',e=>{if(e.detail===0)fn()})}
function create(){if(sheet)return;sheet=document.createElement('section');sheet.id='moonGuide';sheet.hidden=true;sheet.setAttribute('role','dialog');sheet.setAttribute('aria-modal','true');sheet.setAttribute('aria-labelledby','moonGuideTitle');sheet.innerHTML='<div class="moon-guide-sheet"><div class="moon-guide-heading"><span class="moon-guide-seal" aria-hidden="true">☾</span><div><small>月港 · 出发简报</small><h2 id="moonGuideTitle"></h2></div><button id="moonGuideClose" aria-label="关闭说明，返回准备界面">×</button></div><div class="moon-guide-content"><p id="moonGuideGoal"></p><div class="moon-guide-section"><h3>如何行动</h3><p id="moonGuideControl"></p></div><div class="moon-guide-section"><h3>留意什么</h3><p id="moonGuideHazard"></p></div><div class="moon-guide-section moon-guide-tip"><h3>给初次出发的你</h3><p id="moonGuideTip"></p></div><p id="moonGuideWorld"></p><p id="moonGuideRule"></p></div><div class="moon-guide-actions"><button id="moonGuideStart">了解了，出发 →</button><button id="moonGuideSkip">跳过，直接开始</button></div><small class="moon-guide-footnote">说明期间游戏暂停 · 随时可以重新查看</small></div>';document.body.append(sheet);press(sheet.querySelector('#moonGuideClose'),()=>close());press(sheet.querySelector('#moonGuideStart'),()=>close({start:true}));press(sheet.querySelector('#moonGuideSkip'),()=>close({start:true}));}
function close(options={}){if(!sheet||sheet.hidden)return false;sheet.hidden=true;for(const [el,old] of background)el.inert=old;background=[];const run=pending;pending=null;window.dispatchEvent(new CustomEvent('moonguidechange',{detail:{active:false,started:!!options.start}}));previousFocus?.focus?.({preventScroll:true});if(options.start)run?.();return true}
function open(options={},onStart){create();if(!sheet.hidden)close();last={...options};pending=typeof onStart==='function'?onStart:null;previousFocus=document.activeElement;const m=modes[options.mode]||modes.timed;const $=id=>sheet.querySelector('#moonGuide'+id);$('Title').textContent=options.title||m.title;$('Goal').textContent=options.goal||m.goal;$('Control').textContent=options.control||m.control;$('Hazard').textContent=options.hazard||m.hazard;$('Tip').textContent=options.tip||m.tip;const w=worlds[options.world];$('World').textContent=w?`${w[0]} · ${w[1]}`:'';$('World').hidden=!w;$('Rule').textContent=options.rule||'';$('Rule').hidden=!options.rule;$('Start').textContent=onStart?'了解了，出发 →':'返回游戏';$('Skip').hidden=!onStart;background=Array.from(document.body.children).filter(el=>el!==sheet&&!['SCRIPT','STYLE','LINK'].includes(el.tagName)).map(el=>[el,el.inert]);for(const [el]of background)el.inert=true;sheet.hidden=false;sheet.querySelector('.moon-guide-content').scrollTop=0;window.dispatchEvent(new CustomEvent('moonguidechange',{detail:{active:true}}));$('Start').focus({preventScroll:true})}
document.addEventListener('keydown',e=>{if(!sheet||sheet.hidden)return;if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();close();return}if(e.key==='Tab'){const buttons=Array.from(sheet.querySelectorAll('button')).filter(b=>!b.hidden);const at=buttons.indexOf(document.activeElement);const next=(at+(e.shiftKey?-1:1)+buttons.length)%buttons.length;e.preventDefault();buttons[next].focus();return}if([' ','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','w','a','s','d','p','P','q','Q','r','R','e','E','f','F'].includes(e.key)){e.stopImmediatePropagation();if(e.key!==' ')e.preventDefault()}},true);
window.MoonGuide={open,close,reopen:()=>last&&open(last),get active(){return !!sheet&&!sheet.hidden},content:modes};
})();
